@using UniversityCatalog.Services
@inject CatalogService Catalog

<PageTitle>Courses — University Course Catalog</PageTitle>

<nav aria-label="breadcrumb" class="mb-3">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active" aria-current="page">Courses</li>
    </ol>
</nav>

<h1 class="mb-3">
    @if (!string.IsNullOrWhiteSpace(Department))
    {
        var dept = Catalog.GetDepartment(Department);
        @(dept is not null ? $"{dept.IconEmoji} {dept.Name} Courses" : "Courses")
    }
    else
    {
        <text>All Courses</text>
    }
</h1>

<CourseFilters Search="@Search" Department="@Department" Departments="Catalog.GetDepartments()" />

@if (_courses.Count == 0)
{
    <div class="alert alert-info">
        No courses found matching your criteria. Try adjusting your search or filter.
    </div>
}
else
{
    <p class="text-muted mb-3">Showing @_courses.Count course(s)</p>

    @foreach (var course in _courses)
    {
        <CourseCard Course="course" />
    }
}

@code {
    [SupplyParameterFromQuery] public string? Search { get; set; }
    [SupplyParameterFromQuery] public string? Department { get; set; }

    private IReadOnlyList<Course> _courses = [];

    protected override void OnInitialized()
    {
        _courses = Catalog.SearchCourses(Search, Department);
    }
}

@page "/courses/{CourseId}"
@using UniversityCatalog.Services
@inject CatalogService Catalog

@if (_course is null)
{
    <PageTitle>Course Not Found</PageTitle>
    <div class="alert alert-warning">
        <h4>Course not found</h4>
        <p>The course you're looking for doesn't exist. <a href="/courses">Browse all courses</a>.</p>
    </div>
}
else
{
    <PageTitle>@_course.Code @_course.Title — University Course Catalog</PageTitle>

    <nav aria-label="breadcrumb" class="mb-3">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="/courses">Courses</a></li>
            <li class="breadcrumb-item"><a href="/courses?department=@_course.DepartmentId">@_course.DepartmentName</a></li>
            <li class="breadcrumb-item active" aria-current="page">@_course.Code</li>
        </ol>
    </nav>

    <div class="d-flex justify-content-between align-items-start mb-3">
        <div>
            <h1 class="mb-1">@_course.Code — @_course.Title</h1>
            <p class="text-muted">@_course.DepartmentName · @_course.Credits Credits · @_course.Semester</p>
        </div>
        <a href="/enroll?courseId=@_course.Id" class="btn btn-primary">Enroll in This Course</a>
    </div>

    <div class="row">
        <div class="col-lg-8">
            <div class="card mb-3">
                <div class="card-header">
                    <h5 class="mb-0">📋 Description</h5>
                </div>
                <div class="card-body">
                    <p class="mb-0">@_course.Description</p>
                </div>
            </div>

            <InstructorBio Instructor="_course.Instructor" />
        </div>

        <div class="col-lg-4">
            <CourseSchedule Schedule="@_course.Schedule" Location="@_course.Location" Semester="@_course.Semester" />

            <div class="card mb-3">
                <div class="card-header">
                    <h5 class="mb-0">📊 Enrollment</h5>
                </div>
                <div class="card-body">
                    <div class="d-flex justify-content-between mb-1">
                        <span>Enrolled</span>
                        <span>@_course.CurrentEnrollment / @_course.MaxEnrollment</span>
                    </div>
                    @{
                        var pct = (int)((double)_course.CurrentEnrollment / _course.MaxEnrollment * 100);
                        var barClass = pct > 90 ? "bg-danger" : pct > 70 ? "bg-warning" : "bg-success";
                    }
                    <div class="progress">
                        <div class="progress-bar @barClass" role="progressbar"
                             style="width: @(pct)%"
                             aria-valuenow="@_course.CurrentEnrollment"
                             aria-valuemin="0"
                             aria-valuemax="@_course.MaxEnrollment">
                        </div>
                    </div>
                    @if (pct > 90)
                    {
                        <p class="text-danger small mt-2 mb-0">⚠️ This course is nearly full.</p>
                    }
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter] public string? CourseId { get; set; }

    private Course? _course;

    protected override void OnInitialized()
    {
        if (!string.IsNullOrWhiteSpace(CourseId))
        {
            _course = Catalog.GetCourse(CourseId);
        }
    }
}

@page "/enroll"
@using UniversityCatalog.Services
@inject CatalogService Catalog

<PageTitle>Enrollment Request — University Course Catalog</PageTitle>

<nav aria-label="breadcrumb" class="mb-3">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active" aria-current="page">Enroll</li>
    </ol>
</nav>

<h1 class="mb-4">📝 Enrollment Request</h1>

@if (_submitted)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Request Submitted!</h4>
        <p>Thank you, <strong>@_model.FullName</strong> (ID: @_model.StudentId).</p>
        <p>Your enrollment request for <strong>@_selectedCourseName</strong> has been received and is being processed.</p>
        <hr />
        <a href="/courses" class="btn btn-outline-success">Browse More Courses</a>
        <a href="/enroll" class="btn btn-success ms-2">Submit Another Request</a>
    </div>
}
else
{
    <div class="row">
        <div class="col-lg-8">
            <div class="card">
                <div class="card-body">
                    <p class="text-muted mb-4">Fill out the form below to request enrollment in a course. All fields are required.</p>

                    <EditForm method="post" Model="_model" OnValidSubmit="HandleSubmit" FormName="enrollment">
                        <AntiforgeryToken />
                        <DataAnnotationsValidator />
                        <ValidationSummary class="text-danger mb-3" />

                        <div class="mb-3">
                            <label for="fullName" class="form-label">Full Name</label>
                            <InputText id="fullName" @bind-Value="_model.FullName" class="form-control" placeholder="e.g., Jane Doe" />
                            <ValidationMessage For="() => _model.FullName" class="text-danger" />
                        </div>

                        <div class="mb-3">
                            <label for="studentId" class="form-label">Student ID</label>
                            <InputText id="studentId" @bind-Value="_model.StudentId" class="form-control" placeholder="e.g., CS123456" />
                            <ValidationMessage For="() => _model.StudentId" class="text-danger" />
                            <div class="form-text">Format: 2 uppercase letters followed by 6 digits.</div>
                        </div>

                        <div class="mb-4">
                            <label for="courseId" class="form-label">Course</label>
                            <InputSelect id="courseId" @bind-Value="_model.CourseId" class="form-select">
                                <option value="">— Select a course —</option>
                                @foreach (var course in _courses)
                                {
                                    <option value="@course.Id">@course.Code — @course.Title (@course.Credits cr.)</option>
                                }
                            </InputSelect>
                            <ValidationMessage For="() => _model.CourseId" class="text-danger" />
                        </div>

                        <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
                    </EditForm>
                </div>
            </div>
        </div>

        <div class="col-lg-4">
            <div class="card bg-light">
                <div class="card-body">
                    <h6>ℹ️ How It Works</h6>
                    <ol class="small mb-0">
                        <li>Fill out the enrollment form.</li>
                        <li>Your request is reviewed by the registrar.</li>
                        <li>You'll receive a confirmation email within 2 business days.</li>
                        <li>Check your student portal for enrollment status.</li>
                    </ol>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [SupplyParameterFromForm]
    private EnrollmentRequest _model { get; set; } = new();

    [SupplyParameterFromQuery]
    public string? CourseId { get; set; }

    private IReadOnlyList<Course> _courses = [];
    private bool _submitted;
    private string _selectedCourseName = "";

    protected override void OnInitialized()
    {
        _courses = Catalog.GetAllCourses();

        // Pre-select course if linked from a course detail page
        if (!string.IsNullOrWhiteSpace(CourseId) && string.IsNullOrWhiteSpace(_model.CourseId))
        {
            _model.CourseId = CourseId;
        }
    }

    private void HandleSubmit()
    {
        var course = Catalog.GetCourse(_model.CourseId);
        _selectedCourseName = course is not null ? $"{course.Code} — {course.Title}" : _model.CourseId;
        _submitted = true;
    }
}

